NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Habakkuk'

CHAPTERS = {
    1: {
        1: 'Breme, ki ga je videl prerok Habakúk.',
        2: 'Oh Gospod, doklej bom klical in ne boš slišal! Celó klical k tebi o nasilju in ne boš rešil!',
        3: 'Zakaj mi kažeš krivičnost in mi povzročaš, da gledam gorje? Kajti plenjenje in nasilje sta pred menoj in tam so takšni, ki vzdigujejo spor in prepir.',
        4: 'Zatorej je postava ohlapna in sodba nikoli ne gre naprej, kajti zlobni obdaja pravičnega, zato izhaja napačna sodba.',
        5: 'Poglejte med pogane in preudarite in se silno čudite, kajti jaz bom naredil delo, delo v vaših dneh, ki ga ne boste verjeli, čeprav bi vam bilo povedano.',
        6: 'Kajti glejte, vzdignil bom Kaldejce, ki so zagrenjen in nagel narod, ki bo korakal skozi širino dežele, da vzame v last prebivališča, ki niso njihova.',
        7: 'Strašni so in grozni. Njihova sodba in njihovo dostojanstvo bo izšlo iz njih samih.',
        8: '§ Tudi njihovi konji so hitrejši kakor leopardi in bolj kruti kakor večerni volkovi. Njihovi konjeniki se bodo razprostrli in njihovi konjeniki bodo prišli od daleč. Leteli bodo kakor orel, ki hiti, da žre.',
        9: '§ Vsi bodo prišli zaradi nasilja. Njihovi obrazi bodo izpiti kakor vzhodnik in ujetništva bodo zbrali kakor peska.',
        10: 'Norčevali se bodo iz kraljev in princi jim bodo prezir. Zasmehovali bodo vsako oporišče, kajti nagrmadili bodo prah in ga zavzeli.',
        11: 'Potem se bo njegov um spremenil, šel bo mimo in se pohujšal, prištevajoč to svojo moč svojemu bogu.',
        12: 'Mar nisi ti od večnosti, oh Gospod, moj Bog, moj Sveti? Ne bomo umrli. Oh Gospod, za sodbo si jih odredil. Oh mogočni Bog, utrdil si jih za grajanje.',
        13: 'Tvoje oči so preveč čiste, da bi gledal zlo in ne moreš gledati na krivičnost. Zakaj torej gledaš na tiste, ki postopajo zahrbtno in zadržuješ svoj jezik, ko zlobni požira človeka, ki je pravičnejši kakor on?',
        14: 'In ljudi delaš kakor ribe morja, kakor plazeče stvari, ki nimajo nobenega vladarja nad seboj?',
        15: 'Vse izmed njih privlečejo s trnkom, lovijo jih v svojo mrežo in jih zbirajo v svojo vlako; zato se veselijo in so veseli.',
        16: 'Zato darujejo svoji mreži in svoji vrši zažigajo kadilo, ker po njima je njihov delež obilen in njihova hrana obilna.',
        17: 'Ali bodo zato praznili svojo mrežo in ne bodo nenehno prizanašali pobijanju narodov?',
    },
    2: {
        1: 'Stal bom na svoji straži in se postavil na stolp in stražil bom, da vidim kaj mi bo rekel in kaj bom odgovoril, ko bom pograjan.',
        2: 'Gospod mi je odgovoril in rekel: »Zapiši videnje in ga naredi razločnega na ploščah, da bo lahko tekel, kdor ga bo bral.',
        3: 'Kajti še je videnje za določeni čas, toda ob koncu bo govorilo in ne bo lagalo. Čeprav odlaša, čakaj nanj, kajti zagotovo bo prišlo, ne bo odlašalo.',
        4: 'Glej, njegova duša, ki je povzdignjena, ni iskrena v njem, toda pravični bo živel po svoji veri.',
        5: 'Da, prav tako, ker greši z vinom, je ponosen človek niti se ne drži doma, ki svojo željo povečuje kakor pekel in je kakor smrt in ne more biti nasičen, temveč k sebi zbira vse narode in k sebi kopiči vsa ljudstva.',
        6: 'Mar ne bodo vsi ti vzdignili prispodobe zoper njega in zbadljiv pregovor zoper njega in rekli: »Gorje tistemu, ki povečuje to, kar ni njegovo!« Doklej? In tistemu, ki se oblaga z zastavljenimi dobrinami!',
        7: 'Mar se ne bodo nenadoma dvignili tisti, ki te bodo grizli in se prebudili tisti, ki te bodo mučili, ti pa jim boš v plen?',
        8: 'Ker si oplenil mnoge narode, bo ves preostanek ljudstva oplenil tebe zaradi človeške krvi in zaradi nasilja deželi, mestu in vsem, ki prebivajo v njem.',
        9: 'Gorje tistemu, ki hlepi s hudobno pohlepnostjo za svojo hišo, da bi lahko postavil svoje gnezdo na visoko, da bi bil lahko osvobojen pred močjo zla!',
        10: 'Svetoval si sramoto svoji hiši, s tem, da si uničil mnoga ljudstva in si grešil zoper svojo dušo.',
        11: 'Kajti kamen bo vpil iz zidu in bruno iz lesa mu bo odgovarjalo.',
        12: 'Gorje tistemu, ki gradi mesto s krvjo in mesto utrjuje s krivičnostjo!',
        13: 'Glej, mar ni to od Gospoda nad bojevniki, da se bo ljudstvo trudilo v samem ognju in se bo ljudstvo izmučilo za samo ničnost?',
        14: 'Kajti zemlja bo napolnjena s spoznanjem Gospodove slave, kakor vode pokrivajo morje.',
        15: 'Gorje mu, ki daje svojemu bližnjemu piti, ki svoje mehove polaga k njemu in ga dela tudi pijanega, da bi lahko gledal na njihovo nagoto!',
        16: 'Napolnjen si s sramoto namesto s slavo. Pij tudi ti in naj bo tvoja prednja kožica odkrita. Čaša Gospodove desnice bo obrnjena k tebi in sramotno pljuvanje bo na tvoji slavi.',
        17: 'Kajti nasilje Libanona te bo pokrilo in plen živali, ki si jih prestrašil zaradi človeške krvi in zaradi nasilja dežele, mesta in vseh, ki prebivajo v njem.',
        18: 'Kaj koristi rezana podoba, ki jo je njen izdelovalec izrezal; ulita podoba in učiteljica laži, da izdelovalec svojega dela zaupa vanjo, da izdeluje neme malike?',
        19: 'Gorje tistemu, ki govori lesu: »Zbudi se.« Nememu kamnu: »Vstani, ta bo učil!« Glej, ta je prevlečen z zlatom in srebrom in tam, v njegovi sredi, sploh ni nobenega diha.',
        20: 'Toda Gospod je v svojem svetem templju. Naj vsa zemlja ohrani molk pred njim.',
    },
    3: {
        1: 'Molitev preroka Habakúka na Šiginot.',
        2: 'Oh Gospod, slišal sem tvoj govor in bil sem prestrašen. Oh Gospod, oživi svoje delo v sredi let, v sredi let ga daj spoznati, v besu se spomni usmiljenja.',
        3: 'Bog je prišel iz Temána in Sveti z gore Parán. Sela. Njegova slava je pokrila nebo in zemlja je bila polna njegove hvale.',
        4: 'Njegov sijaj je bil kakor svetloba; imel je rogove, izhajajoče iz njegove roke in tam je bilo skrivališče njegove moči.',
        5: 'Pred njim je odšla kužna bolezen in goreče oglje je šlo naprej ob njegovih stopalih.',
        6: 'Stal je in izmeril zemljo. Pogledal je in razgnal narode in večne gore so bile razkropljene, starodavni hribi so se upognili. Njegove poti so večne.',
        7: 'Videl sem kušánske šotore v stiski in zavese midjánske dežele so trepetale.',
        8: 'Mar je bil Gospod nezadovoljen zoper reke? Je bila tvoja jeza zoper reke? Je bil tvoj bes zoper morje, da si jahal na svojih konjih in svojih bojnih vozovih rešitve duš?',
        9: 'Tvoj lok je bil razgaljen, glede na prisege rodov, celo tvojo besedo. Sela. Zemljo si oklenil z rekami.',
        10: 'Gore so te videle in so trepetale, preplavljanje vodá je šlo mimo, globina je izustila svoj glas in svoje roke vzdignila na visoko.',
        11: 'Sonce in luna sta mirno stala v svojem prebivališču. Ob svetlobi tvojih puščic sta šla in ob siju tvoje lesketajoče sulice.',
        12: 'V ogorčenju si korakal skozi deželo, pogane si mlatil v jezi.',
        13: 'Šel si naprej zaradi rešitve duš svojega ljudstva, celó zaradi rešitve duš s svojim maziljenim. Ti raniš poglavarja hiše zlobnih z razkritjem temelja do vratu. Sela.',
        14: 'Z njegovimi kopji si prebodel poglavarja njegovih vasi. Ven so prišli kakor vrtinčast veter, da me razkropijo. Njihovo razveseljevanje je bilo kakor, da bi na skrivaj požrli ubogega.',
        15: 'Skozi morje si hodil s svojimi konji, skozi kup velikih vodá.',
        16: 'Ko sem slišal, je moj trebuh trepetal, moje ustnice so drgetale ob glasu. Gniloba je vstopila v moje kosti in v sebi sem trepetal, da bi lahko počival na dan stiske. Ko prihaja gor k ljudstvu, jih bo preplavil s svojimi krdeli.',
        17: 'Čeprav figovo drevo ne bo cvetelo niti ne bo sadu na trtah, [čeprav] bo trud oljke odpovedal in polja ne bodo obrodila nobene hrane; [čeprav] bo trop odrezan od staje in v hlevih ne bo črede,',
        18: 'se bom vendar veselil v Gospodu, užival bom v Bogu rešitve moje duše.',
        19: 'Gospod Bog je moja moč in on bo moja stopala naredil podobna košutinim stopalom in dal mi bo, da hodim na svojih visokih krajih. Vodilnemu pevcu na moja glasbila na strune.',
    },
}
